package compiler;

import utils.DiagnosticsHandler;

import java.io.Reader;
import java.util.List;
import java.util.Objects;

/**
 * Entry point of the whole pipeline: FCL program to Vivado HLS C++ files.
 * <p>
 * The pipeline is lexer + parser (symbol table and rule block AST), lowering to the controller model of
 * Luca Sarramone's generator, and code generation with the ported generator. The generated files follow the
 * naming of that generator: {@code <base>_out.cpp}, {@code <base>_out.h} and {@code <base>_outTB.cpp}.
 * </p>
 * <p>
 * Not implemented yet: the expected behavior is fixed by {@code LucaGoldenIT}, which compares the output
 * against the reference files generated by Luca's original tool.
 * </p>
 *
 * @author Matias Ortiz
 * @author Victoriano Etcheverría
 * @version 1.0
 * @since 1.0
 */
public final class FlcCompiler {
    private final DiagnosticsHandler diagnostics;

    /**
     * Creates a compiler that reports every lexical, syntactic and semantic problem to the given handler.
     *
     * @param diagnostics collector of errors and warnings of the whole pipeline
     */
    public FlcCompiler(final DiagnosticsHandler diagnostics) {
        this.diagnostics = Objects.requireNonNull(diagnostics, "diagnostics");
    }

    /**
     * Compiles an FCL program.
     *
     * @param source   the FCL program
     * @param baseName base name of the generated files (it also appears inside the test bench)
     * @return the generated files; empty if the program has errors (see the diagnostics handler)
     * @throws UnsupportedOperationException always, until lowering and code generation exist
     */
    public List<GeneratedFile> compile(final Reader source, final String baseName) {
        Objects.requireNonNull(source, "source");
        Objects.requireNonNull(baseName, "baseName");
        throw new UnsupportedOperationException(
                "FlcCompiler.compile: lowering and code generation are not implemented yet (see LucaGoldenIT)");
    }
}
